import * as AasStringification from "../src/stringification";
import * as AasTypes from "../src/types";

test("Color stringification round-trip Red", () => {
  const literal = AasTypes.Color.Red;

  const text = AasStringification.mustColorToString(literal);
  expect(text).toStrictEqual("Red");

  const nullableText = AasStringification.colorToString(literal);
  expect(nullableText).toStrictEqual("Red");

  const parsed = AasStringification.colorFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("Color stringification round-trip Green", () => {
  const literal = AasTypes.Color.Green;

  const text = AasStringification.mustColorToString(literal);
  expect(text).toStrictEqual("Green");

  const nullableText = AasStringification.colorToString(literal);
  expect(nullableText).toStrictEqual("Green");

  const parsed = AasStringification.colorFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("Color from invalid string", () => {
  const parsed = AasStringification.colorFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("Color invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <AasTypes.Color>9007199254740991;

  expect(AasStringification.colorToString(invalidLiteral)).toBeNull();
  expect(() => AasStringification.mustColorToString(invalidLiteral)).toThrow();
});

